ia_urls=[]
ia_links=[]
for d in IA_COUNTIES:
    sources=[('Iowa DNR — Private Sewage Disposal and Septage', IA_DNR)] + d['sources']
    sections=[
        ('Iowa state and county framework', 'Iowa DNR states that local boards of health have primary responsibility for regulating private sewage disposal systems serving four homes or fewer or fewer than 15 people, while counties must meet the state minimum standards. Larger public systems are primarily regulated by Iowa DNR. County procedures and locally adopted requirements therefore matter for ordinary residential septic projects.')
    ] + d['sections']
    ia_urls.append(write_county_page('Iowa','iowa',d['county'],d['authority'],d['contact'],sections,sources,verified='August 30, 2026'))
    ia_links.append((d['county'], d['authority']))

write_hub(
    'Iowa','iowa',sorted(ia_links),
    'Iowa DNR establishes minimum private sewage disposal standards, while local boards of health have primary responsibility for ordinary private systems. These guides include only counties where current official sources support the local permitting authority and substantive county procedures or requirements.',
    'This initial Iowa batch covers Polk, Linn, Story, and Johnson counties. SepticScope does not extrapolate county contractor licensing, local system restrictions, pumping requirements, permit duration, site-evaluation procedure, or other local rules to counties where they have not been verified.'
)

